```js
import express from 'express';
import { createServer } from 'http';
import { Server } from 'socket.io';
import jwt from 'jsonwebtoken';
import { assignChunk } from './chunks.js';

const app = express();
app.get('/health', (_req, res) => res.json({ ok: true }));
const http = createServer(app);
const io = new Server(http, { cors: { origin: (process.env.CORS_ORIGINS ?? '').split(',').filter(Boolean) } });

io.use((socket, next) => {
  try {
    const token = socket.handshake.auth?.token;
    const payload = jwt.verify(token, process.env.SUPABASE_JWT_SECRET);
    socket.data.userId = payload.sub;
    next();
  } catch { next(new Error('unauthorized')); }
});

io.on('connection', (socket) => {
  socket.on('chunk:get', async (ack) => {
    try { ack({ ok: true, base: await assignChunk(socket.data.userId) }); }
    catch (e) { ack({ ok: false, error: 'chunk_failed' }); }
  });
});

http.listen(process.env.PORT ?? 3000);
```

`server/src/chunks.js` — scatter placement + efficiency (queries use the server-side pool; Postgres/Redis stay on the private Docker network):

```js
import { getEfficiency } from '../../shared/world.js';
import { db } from './db.js';

export async function assignChunk(userId) {
  const existing = await db.query('select * from bases where owner_id = $1', [userId]);
  if (existing.rows[0]) return existing.rows[0];
  for (let attempt = 0; attempt &lt; 50; attempt++) {
    const cx = Math.floor(Math.random() * 100), cy = Math.floor(Math.random() * 100);
    const world_x = (cx - 50) * 200 + Math.random() * 200;
    const world_y = (cy - 50) * 200 + Math.random() * 200;
    const clash = await db.query(
      'select 1 from bases where power(world_x - $1, 2) + power(world_y - $2, 2) &lt; power($3, 2) limit 1',
      [world_x, world_y, attempt &lt; 25 ? 150 : 75]);
    if (clash.rows.length) continue;
    try {
      const r = await db.query(
        `insert into bases (owner_id, chunk_x, chunk_y, world_x, world_y, efficiency_cached)
         values ($1,$2,$3,$4,$5,$6) returning *`,
        [userId, cx, cy, world_x, world_y, getEfficiency(world_x, world_y)]);
      return r.rows[0];
    } catch { /* chunk taken concurrently — retry */ }
  }
  throw new Error('world_full');
}
```

